<div class="container admin-main"><div class="admin-title-row"><div><h1>سرنخ‌های فروش</h1><p>فرم‌های تماس و درخواست پیش‌فاکتور در یک مسیر پیگیری ثبت می‌شوند.</p></div><span class="status-badge">نمایش آخرین ۱۵۰ درخواست</span></div>
<div class="admin-panel"><h2>درخواست‌های ثبت‌شده</h2><?php if ($leads === []): ?><div class="empty-state">هنوز درخواستی ثبت نشده است. درخواست‌های سایت پس از ارسال فرم در این بخش ظاهر می‌شوند.</div><?php else: ?><div class="table-wrap"><table class="data-table lead-table"><thead><tr><th>مخاطب و تماس</th><th>نیاز</th><th>ثبت‌شده</th><th>وضعیت و یادداشت پیگیری</th></tr></thead><tbody>
<?php foreach ($leads as $lead): ?><tr><td><strong><?= e($lead['full_name']) ?></strong><br><?php if ($lead['company_name']): ?><span class="muted"><?= e($lead['company_name']) ?><br></span><?php endif; ?><a href="tel:<?= e(preg_replace('/[^0-9+]/', '', $lead['phone'])) ?>" dir="ltr"><?= e($lead['phone']) ?></a><?php if ($lead['email']): ?><br><a href="mailto:<?= e($lead['email']) ?>" dir="ltr"><?= e($lead['email']) ?></a><?php endif; ?></td><td><?= e($lead['requested_service'] ?: ($lead['service_title'] ?? '—')) ?><br><span class="muted"><?= e(['consultation'=>'مشاوره','quote'=>'پیش‌فاکتور','contact'=>'تماس'][$lead['lead_type']] ?? 'تماس') ?> · منبع: <?= e($lead['source']) ?></span><?php if ($lead['description']): ?><details class="lead-description"><summary>شرح درخواست</summary><p><?= nl2br(e($lead['description'])) ?></p></details><?php endif; ?><?php if (!empty($lead['notes'])): ?><details class="lead-description"><summary>تاریخچه پیگیری (<?= count($lead['notes']) ?>)</summary><?php foreach ($lead['notes'] as $history): ?><p><strong><?= e($history['author'] ?: 'کارشناس') ?></strong> · <time dir="ltr"><?= e($history['created_at']) ?></time><br><?= nl2br(e($history['note'])) ?></p><?php endforeach; ?></details><?php endif; ?></td><td dir="ltr"><?= e($lead['created_at']) ?></td><td><form action="<?= e(site_url('/admin/leads/update')) ?>" method="post" class="lead-update-form"><?= csrf_field() ?><input type="hidden" name="lead_id" value="<?= (int) $lead['id'] ?>"><label class="sr-only" for="status-<?= (int) $lead['id'] ?>">مرحله پیگیری</label><select id="status-<?= (int) $lead['id'] ?>" name="status"><?php foreach (['new'=>'درخواست جدید','contacted'=>'تماس اولیه','needs_assessment'=>'نیازسنجی','proposal_sent'=>'ارسال پیشنهاد','negotiation'=>'مذاکره','won'=>'برنده‌شده','lost'=>'از دست‌رفته'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $lead['status']===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><label class="sr-only" for="follow-<?= (int) $lead['id'] ?>">پیگیری بعدی</label><input id="follow-<?= (int) $lead['id'] ?>" type="datetime-local" name="next_follow_up_at" value="<?= e($lead['next_follow_up_at'] ? substr(str_replace(' ', 'T', $lead['next_follow_up_at']),0,16) : '') ?>"><label class="sr-only" for="note-<?= (int) $lead['id'] ?>">یادداشت پیگیری</label><textarea id="note-<?= (int) $lead['id'] ?>" name="note" maxlength="4000" placeholder="یادداشت پیگیری (اختیاری)"></textarea><button class="btn btn-dark" type="submit">ذخیره پیگیری</button></form></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></div></div>
